input.command:
export PGPORT=5433
su - postgres -c "psql -p 5433 -v ON_ERROR_STOP=1 <<'SQL'
DO \$\$
BEGIN
  IF NOT EXISTS (SELECT FROM pg_roles WHERE rolname = 'benchmark_user') THEN
    CREATE ROLE benchmark_user LOGIN SUPERUSER PASSWORD 'benchmark_pass';
  ELSE
    ALTER ROLE benchmark_user WITH LOGIN SUPERUSER PASSWORD 'benchmark_pass';
  END IF;
END
\$\$;
SELECT 'role_ok' AS status;
SQL"
echo "--- create db ---"
su - postgres -c "psql -p 5433 -tAc \"SELECT 1 FROM pg_database WHERE datname='benchmark_db'\"" | grep -q 1 || su - postgres -c "createdb -p 5433 -O benchmark_user benchmark_db"
su - postgres -c "psql -p 5433 -c '\l benchmark_db'"
